/**
 * Pure tests for the crq repair selection port.
 *
 * The oracle fixture is generated by
 * `apps/crq-python/repair_selection_vectors.py` from the PRODUCTION Python
 * `crq_repair.bounded.select_job`, `drain_order` and `drain_job`. Every Git
 * read, inbox file, queue record, triage row and started marker is injected;
 * the test compares the canonical result bytes and the exact ordered Git
 * reads, so ordering, run/stale/skip classification, the bound legacy job and
 * the explicit selected job id move only when Python moves.
 *
 * No process, filesystem read/write, clock or network participates.
 */
import { readFileSync } from 'node:fs';
import { describe, expect, test } from 'vitest';
import {
  drainJob,
  drainOrder,
  REPAIR_DEFAULT_REF,
  selectJob,
  type RepairDrainInput,
  type RepairInboxEntry,
  type RepairJobFile,
  type RepairSelectionGit,
} from '../../../src/policy/crq/repairSelection.js';
import {
  JsonNumber,
  JsonObject,
  parseJsonValue,
  type JsonValue,
} from '../../../src/policy/crq/jsonValue.js';
import { pythonJsonText, receiptJsonText } from '../../../src/policy/crq/pythonJson.js';

const FIXTURE_URL = new URL(
  '../../../apps/crq-python/fixtures/crq-repair-selection/cases.json',
  import.meta.url,
);
const fixture = asObject(parseJsonValue(readFileSync(FIXTURE_URL, 'utf8')));
const cases = asArray(fixture.get('cases')).map((entry) => asObject(entry));

function asObject(value: JsonValue | undefined): JsonObject {
  if (!(value instanceof JsonObject)) throw new Error('fixture value is not an object');
  return value;
}

function asArray(value: JsonValue | undefined): JsonValue[] {
  if (!Array.isArray(value)) throw new Error('fixture value is not an array');
  return value;
}

function string(value: JsonValue | undefined): string {
  if (typeof value !== 'string') throw new Error('fixture value is not a string');
  return value;
}

function numberValue(value: JsonValue | undefined): number {
  if (!(value instanceof JsonNumber)) throw new Error('fixture value is not a number');
  return value.kind === 'int' ? Number(value.integer as bigint) : (value.float as number);
}

function optionalString(value: JsonValue | undefined): string | undefined {
  return typeof value === 'string' ? value : undefined;
}

function caseByName(name: string): JsonObject {
  const found = cases.find((entry) => entry.get('name') === name);
  if (found === undefined) throw new Error(`missing fixture case ${name}`);
  return found;
}

interface InjectedGit {
  readonly git: RepairSelectionGit;
  readonly reads: string[];
}

function injectedGit(entry: JsonObject): InjectedGit {
  const spec = asObject(entry.get('git'));
  const blobs = asObject(spec.get('blobs'));
  const branches = asObject(spec.get('branches'));
  const ancestors = new Set(
    asArray(spec.get('ancestors')).map((pair) => {
      const [a, b] = asArray(pair);
      return `${string(a)}\u0000${string(b)}`;
    }),
  );
  const tip = string(spec.get('tip'));
  const reads: string[] = [];
  const git: RepairSelectionGit = {
    currentTip: () => {
      reads.push(`rev-parse ${REPAIR_DEFAULT_REF}`);
      return tip;
    },
    checkedBlob: (ref, path) => {
      reads.push(`rev-parse ${ref}:${path}`);
      return optionalString(blobs.get(`${ref}:${path}`));
    },
    blobAt: (ref, path) => {
      reads.push(`rev-parse --verify --quiet ${ref}:${path}`);
      return optionalString(blobs.get(`${ref}:${path}`));
    },
    isAncestor: (ancestor, descendant) => {
      reads.push(`merge-base --is-ancestor ${ancestor} ${descendant}`);
      return ancestors.has(`${ancestor}\u0000${descendant}`);
    },
    originBranchHead: (branch) => {
      reads.push(`rev-parse --verify --quiet refs/remotes/origin/${branch}^{commit}`);
      return optionalString(branches.get(branch));
    },
  };
  return { git, reads };
}

function jobFileOf(entry: JsonObject): RepairJobFile {
  const raw = entry.get('job_raw');
  if (typeof raw === 'string') {
    try {
      return { kind: 'value', value: parseJsonValue(raw) };
    } catch {
      return { kind: 'unreadable' };
    }
  }
  const job = entry.get('job');
  if (job === undefined || job === null) return { kind: 'unreadable' };
  return { kind: 'value', value: job };
}

function triageRowTextOf(entry: JsonObject): string | undefined {
  const raw = entry.get('triage_row_raw');
  if (typeof raw === 'string') return raw;
  const row = entry.get('triage_row');
  if (row === undefined || row === null) return undefined;
  return pythonJsonText(row, {
    asciiOnly: true,
    sortKeys: true,
    keyOrder: 'code-point',
    indent: 2,
    trailingNewline: true,
  });
}

function drainInputOf(entry: JsonObject): { input: RepairDrainInput; reads: string[] } {
  const { git, reads } = injectedGit(entry);
  return {
    input: {
      jobId: string(entry.get('job_id')),
      jobFile: jobFileOf(entry),
      queue: asObject(entry.get('queue')),
      triageRowText: triageRowTextOf(entry),
      started: entry.get('started') === true,
      git,
    },
    reads,
  };
}

function selectInputOf(entry: JsonObject) {
  const { git, reads } = injectedGit(entry);
  return {
    input: {
      jobId: string(entry.get('job_id')),
      sourceSha: string(entry.get('source_sha')),
      findingSha256: optionalString(entry.get('finding_sha256')) ?? '',
      jobFile: jobFileOf(entry),
      queue: asObject(entry.get('queue')),
      triageRowText: triageRowTextOf(entry),
      git,
    },
    reads,
  };
}

function withoutErrorType(expected: JsonObject): JsonObject {
  return new JsonObject(expected.entries.filter(([key]) => key !== 'error_type'));
}

function drainActual(outcome: ReturnType<typeof drainJob>): JsonObject {
  const refusal = outcome.status === 'run' ? null : outcome.refusal;
  const job = outcome.job;
  return new JsonObject([
    ['status', outcome.status],
    ['refusal', refusal],
    ['job', job],
    ['job_keys', job === null ? null : job.entries.map(([key]) => key)],
  ]);
}

function selectActual(result: ReturnType<typeof selectJob>): JsonObject {
  if (!result.ok) {
    return new JsonObject([
      ['ok', false],
      ['refusal', result.refusal],
    ]);
  }
  return new JsonObject([
    ['ok', true],
    ['selectedJobId', result.selectedJobId],
    ['job', result.job],
    ['job_keys', result.job.entries.map(([key]) => key)],
    [
      'selection',
      new JsonObject([
        ['state', result.selection.state],
        ['canonicalDelivery', result.selection.canonicalDelivery],
        ['severity', result.selection.severity],
        ['base', result.selection.base],
        ['jobs', [...result.selection.jobs]],
        ['originJob', result.selection.originJob],
        ['revalidationSha256', result.selection.revalidationSha256],
      ]),
    ],
  ]);
}

function canonical(value: JsonValue | Record<string, JsonValue>): string {
  return receiptJsonText(value);
}

/** Replace every `origin_job` value, preserving the surrounding document. */
function replaceOriginJob(value: JsonValue, origin: JsonValue): JsonValue {
  if (value instanceof JsonObject) {
    return new JsonObject(
      value.entries.map(([key, child]) => [
        key,
        key === 'origin_job' ? origin : replaceOriginJob(child, origin),
      ]),
    );
  }
  if (Array.isArray(value)) return value.map((child) => replaceOriginJob(child, origin));
  return value;
}

/** Replace every value stored under `key`, preserving the surrounding document. */
function replaceKey(value: JsonValue, key: string, replacement: JsonValue): JsonValue {
  if (value instanceof JsonObject) {
    return new JsonObject(
      value.entries.map(([name, child]) => [
        name,
        name === key ? replacement : replaceKey(child, key, replacement),
      ]),
    );
  }
  if (Array.isArray(value)) return value.map((child) => replaceKey(child, key, replacement));
  return value;
}

describe('repair selection oracle parity', () => {
  test('fixture shape and every outcome is present', () => {
    expect(string(fixture.get('schema'))).toBe('cq.crq-repair-selection-vector/v1');
    expect(string(fixture.get('default_ref'))).toBe(REPAIR_DEFAULT_REF);
    const kinds = new Set(cases.map((entry) => string(entry.get('kind'))));
    expect(kinds).toEqual(new Set(['order', 'drain', 'select']));
    const statuses = new Set(
      cases
        .filter((entry) => entry.get('kind') === 'drain')
        .map((entry) => string(asObject(entry.get('expected')).get('status'))),
    );
    expect(statuses).toEqual(new Set(['run', 'stale', 'skip']));
    const names = cases.map((entry) => string(entry.get('name')));
    expect(new Set(names).size).toBe(names.length);
  });

  for (const entry of cases) {
    const name = string(entry.get('name'));
    const kind = string(entry.get('kind'));
    if (kind === 'order') {
      test(`oracle order ${name}`, () => {
        const entries: RepairInboxEntry[] = asArray(entry.get('entries')).map((raw) => {
          const item = asObject(raw);
          return {
            name: string(item.get('name')),
            mtime: numberValue(item.get('mtime')),
            symlink: item.get('symlink') === true,
          };
        });
        const expected = asObject(entry.get('expected'));
        expect(drainOrder(entries)).toEqual(
          asArray(expected.get('jobs')).map((job) => string(job)),
        );
      });
    }
  }

  for (const entry of cases) {
    const name = string(entry.get('name'));
    if (string(entry.get('kind')) !== 'drain') continue;
    test(`oracle drain ${name}`, () => {
      const { input, reads } = drainInputOf(entry);
      const outcome = drainJob(input);
      expect(canonical(drainActual(outcome))).toBe(canonical(asObject(entry.get('expected'))));
      expect(reads).toEqual(asArray(entry.get('git_reads')).map((read) => string(read)));
    });
  }

  for (const entry of cases) {
    const name = string(entry.get('name'));
    if (string(entry.get('kind')) !== 'select') continue;
    test(`oracle select ${name}`, () => {
      const { input, reads } = selectInputOf(entry);
      const result = selectJob(input);
      expect(canonical(selectActual(result))).toBe(
        canonical(withoutErrorType(asObject(entry.get('expected')))),
      );
      expect(reads).toEqual(asArray(entry.get('git_reads')).map((read) => string(read)));
    });
  }
});

describe('repair selection ordering', () => {
  test('an empty inbox selects nothing', () => {
    expect(drainOrder([])).toEqual([]);
  });

  test('mtime orders first and the file name breaks ties', () => {
    expect(
      drainOrder([
        { name: 'crq-late.json', mtime: 30, symlink: false },
        { name: 'crq-tie-b.json', mtime: 20, symlink: false },
        { name: 'crq-tie-a.json', mtime: 20, symlink: false },
        { name: 'crq-early.json', mtime: 10, symlink: false },
      ]),
    ).toEqual(['crq-early', 'crq-tie-a', 'crq-tie-b', 'crq-late']);
  });

  test('the glob, job-id grammar and symlink filter are exact', () => {
    expect(
      drainOrder([
        { name: 'crq-valid.json', mtime: 5, symlink: false },
        { name: '.hidden.json', mtime: 1, symlink: false },
        { name: 'not-a-job.json', mtime: 2, symlink: false },
        { name: 'crq-upper.JSON', mtime: 3, symlink: false },
        { name: 'crq-link.json', mtime: 0.5, symlink: true },
        { name: 'crq-a.json.json', mtime: 4, symlink: false },
      ]),
    ).toEqual(['crq-a.json', 'crq-valid']);
  });
});

describe('repair selection refusal cases', () => {
  const base = caseByName('legacy-run-binds-pin');

  test('every non-queued queue state is skipped, never selected', () => {
    for (const state of ['ready', 'done', 'publish_failed', 'published', 'failed', 'stale']) {
      const entry = base.entries.find(([key]) => key === 'queue')?.[1];
      const queue = asObject(entry);
      const item = asObject(asArray(queue.get('items'))[0]);
      const runs = asObject(item.get('repair_runs'));
      const record = asObject(runs.get('run1'));
      const replaced = new JsonObject(
        runs.entries.map(([key, value]) => [
          key,
          key === 'run1'
            ? new JsonObject(record.entries.map(([k, v]) => [k, k === 'state' ? state : v]))
            : value,
        ]),
      );
      const nextItem = new JsonObject(
        item.entries.map(([key, value]) => [key, key === 'repair_runs' ? replaced : value]),
      );
      const nextQueue = new JsonObject(
        queue.entries.map(([key, value]) => [key, key === 'items' ? [nextItem] : value]),
      );
      const { input } = drainInputOf(base);
      const outcome = drainJob({ ...input, queue: nextQueue });
      expect(outcome.status).toBe('skip');
      if (outcome.status === 'run') throw new Error('unreachable');
      expect(outcome.refusal).toBe('no-queued-run');
    }
  });

  test('all-skipped inbox yields only skip outcomes', () => {
    const { input } = drainInputOf(base);
    const outcomes = ['crq-a-F1', 'crq-b-F1'].map((jobId) =>
      drainJob({ ...input, jobId, jobFile: { kind: 'unreadable' } }),
    );
    expect(outcomes.map((outcome) => outcome.status)).toEqual(['skip', 'skip']);
    expect(outcomes.map((outcome) => (outcome.status === 'run' ? null : outcome.refusal))).toEqual([
      'job-unreadable',
      'job-unreadable',
    ]);
  });

  test('an invalid job id cannot escape the inbox', () => {
    const { input } = drainInputOf(base);
    const outcome = drainJob({ ...input, jobId: '../escape' });
    expect(outcome.status).toBe('skip');
    if (outcome.status === 'run') throw new Error('unreachable');
    expect(outcome.refusal).toBe('job-id-invalid');
  });

  test('a malformed queue is a typed skip, not an exception', () => {
    const { input } = drainInputOf(base);
    for (const queue of [new JsonObject([]), new JsonObject([['items', 'not-an-array']])]) {
      const outcome = drainJob({ ...input, queue });
      expect(outcome.status).toBe('skip');
      if (outcome.status === 'run') throw new Error('unreachable');
      expect(outcome.refusal).toBe('selection-malformed');
    }
  });

  test('a missing source blob is a typed stale/skip, never a crash', () => {
    const entry = caseByName('prepared-run');
    const prepared = drainInputOf(entry);
    const withoutBlob: RepairSelectionGit = {
      ...prepared.input.git,
      checkedBlob: () => undefined,
    };
    const outcome = drainJob({ ...prepared.input, git: withoutBlob });
    expect(outcome.status).toBe('skip');
    if (outcome.status === 'run') throw new Error('unreachable');
    expect(outcome.refusal).toBe('source-blob-unreadable');
  });

  test('a drain result never mutates the parsed job', () => {
    const entry = caseByName('legacy-run-binds-pin');
    const { input } = drainInputOf(entry);
    const before = canonical(entry.get('job') as JsonValue);
    const outcome = drainJob(input);
    expect(outcome.status).toBe('run');
    expect(canonical(entry.get('job') as JsonValue)).toBe(before);
    if (outcome.status !== 'run' || !(input.jobFile.kind === 'value')) return;
    expect(outcome.job).not.toBe(input.jobFile.value);
  });
});

describe('repair explicit selection', () => {
  test('exactly one selected job id is returned with verified facts', () => {
    const entry = caseByName('select-prepared');
    const { input } = selectInputOf(entry);
    const result = selectJob(input);
    expect(result.ok).toBe(true);
    if (!result.ok) return;
    expect(result.selectedJobId).toBe('crq-revalidated-fixture-F1');
    expect(result.selection).toEqual({
      state: 'queued',
      canonicalDelivery: 'verified',
      severity: 'repairable',
      base: 'a'.repeat(40),
      jobs: ['crq-revalidated-fixture-F1'],
      originJob: 'crq-origin-F1',
      revalidationSha256: result.selection.revalidationSha256,
    });
  });

  test('structurally equal origin_job values from independent documents select', () => {
    const entry = caseByName('select-prepared');
    const { input } = selectInputOf(entry);
    if (input.jobFile.kind !== 'value' || !(input.jobFile.value instanceof JsonObject)) {
      throw new Error('select-prepared job is not an object');
    }

    // Two equal, non-string values: Python compares `origin_job` with `==`,
    // so separately parsed documents must select. This value is schema
    // invalid and can only be constructed by hand.
    const jobText = receiptJsonText(
      replaceOriginJob(
        input.jobFile.value,
        new JsonObject([
          ['id', 'crq-origin-F1'],
          ['round', JsonNumber.int(1)],
        ]),
      ),
    );
    const queueText = receiptJsonText(
      replaceOriginJob(
        input.queue,
        new JsonObject([
          ['id', 'crq-origin-F1'],
          ['round', JsonNumber.int(1)],
        ]),
      ),
    );
    const independentJob = asObject(parseJsonValue(jobText));
    const independentQueue = asObject(parseJsonValue(queueText));
    const record = asObject(
      asObject(asArray(independentQueue.get('items'))[0]).get('repair_runs'),
    ).get('revalidated-fixture');
    const jobOrigin = independentJob.get('origin_job');
    const recordOrigin = asObject(record).get('origin_job');
    expect(jobOrigin).toEqual(recordOrigin);
    expect(jobOrigin).not.toBe(recordOrigin);

    const result = selectJob({
      ...input,
      jobFile: { kind: 'value', value: independentJob },
      queue: independentQueue,
    });
    expect(result.ok).toBe(true);
    if (!result.ok) return;
    expect(result.selection.originJob).toEqual(jobOrigin);
  });

  test('numeric and boolean item ids match across independently parsed documents', () => {
    const entry = caseByName('select-prepared');
    const { input } = selectInputOf(entry);
    if (input.jobFile.kind !== 'value' || !(input.jobFile.value instanceof JsonObject)) {
      throw new Error('select-prepared job is not an object');
    }
    const jobValue = input.jobFile.value;

    // Production item ids are `JOB_ID` strings; these pairs are schema invalid
    // and can only be constructed by hand. Python compares
    // `i['id'] == job['item']` with `==`, so `1` matches `1.0` and `true`
    // matches `1`. Each document is serialised and re-parsed separately, so no
    // value instance is shared between the job and the queue.
    const select = (item: JsonValue, id: JsonValue) => {
      const job = asObject(parseJsonValue(receiptJsonText(replaceKey(jobValue, 'item', item))));
      const queue = asObject(parseJsonValue(receiptJsonText(replaceKey(input.queue, 'id', id))));
      expect(job.get('item')).not.toBe(asObject(asArray(queue.get('items'))[0]).get('id'));
      return selectJob({ ...input, jobFile: { kind: 'value', value: job }, queue });
    };

    expect(select(JsonNumber.int(1), JsonNumber.float(1)).ok).toBe(true);
    expect(select(JsonNumber.float(1), JsonNumber.int(1)).ok).toBe(true);
    expect(select(true, JsonNumber.int(1)).ok).toBe(true);
    expect(select(JsonNumber.int(1), true).ok).toBe(true);
    expect(select(JsonNumber.int(1), JsonNumber.int(2))).toEqual({
      ok: false,
      refusal: 'no-queued-run',
    });
    expect(select('1', JsonNumber.int(1))).toEqual({
      ok: false,
      refusal: 'no-queued-run',
    });
  });

  test('non-finite origin_job values follow Python: NaN never equal, infinities equal', () => {
    const entry = caseByName('select-prepared');
    const { input } = selectInputOf(entry);
    if (input.jobFile.kind !== 'value' || !(input.jobFile.value instanceof JsonObject)) {
      throw new Error('select-prepared job is not an object');
    }
    const jobValue = input.jobFile.value;
    // Python's JSON reader accepts the non-standard non-finite constants.
    const constant = (raw: string): JsonNumber =>
      JsonNumber.float(
        raw === 'Infinity' ? Infinity : raw === '-Infinity' ? -Infinity : Number.NaN,
      );
    const parseDoc = (value: JsonValue, origin: JsonValue): JsonObject =>
      asObject(
        parseJsonValue(receiptJsonText(replaceOriginJob(value, origin)), {
          parseConstant: constant,
        }),
      );
    const select = (jobOrigin: JsonValue, queueOrigin: JsonValue) =>
      selectJob({
        ...input,
        jobFile: {
          kind: 'value',
          value: parseDoc(jobValue, jobOrigin),
        },
        queue: parseDoc(input.queue, queueOrigin),
      });

    expect(select(JsonNumber.float(Number.NaN), JsonNumber.float(Number.NaN))).toEqual({
      ok: false,
      refusal: 'revalidation-lineage-mismatch',
    });
    const nested = new JsonObject([['deep', [JsonNumber.float(Number.NaN)]]]);
    expect(select(nested, nested)).toEqual({
      ok: false,
      refusal: 'revalidation-lineage-mismatch',
    });
    // Python's `inf == inf` is true and `inf != -inf`.
    expect(select(JsonNumber.float(Infinity), JsonNumber.float(Infinity)).ok).toBe(true);
    expect(select(JsonNumber.float(Infinity), JsonNumber.float(-Infinity))).toEqual({
      ok: false,
      refusal: 'revalidation-lineage-mismatch',
    });
  });

  test('origin_job lineages compare with Python value equality', () => {
    const entry = caseByName('select-prepared');
    const { input } = selectInputOf(entry);
    if (input.jobFile.kind !== 'value' || !(input.jobFile.value instanceof JsonObject)) {
      throw new Error('select-prepared job is not an object');
    }
    const jobValue = input.jobFile.value;
    const parseDoc = (value: JsonValue, origin: JsonValue): JsonObject =>
      asObject(parseJsonValue(receiptJsonText(replaceOriginJob(value, origin))));
    const select = (jobOrigin: JsonValue, queueOrigin: JsonValue) =>
      selectJob({
        ...input,
        jobFile: {
          kind: 'value',
          value: parseDoc(jobValue, jobOrigin),
        },
        queue: parseDoc(input.queue, queueOrigin),
      });

    // Python `==`: `1 == 1.0`, `True == 1`, and `[False] == [0]`.
    expect(select(JsonNumber.int(1), JsonNumber.int(1)).ok).toBe(true);
    expect(select(JsonNumber.int(1), JsonNumber.float(1)).ok).toBe(true);
    expect(select(JsonNumber.float(1), JsonNumber.int(1)).ok).toBe(true);
    expect(select(true, JsonNumber.int(1)).ok).toBe(true);
    // A falsy lineage is refused as missing before the comparison, as Python does.
    expect(select(JsonNumber.int(0), false)).toEqual({ ok: false, refusal: 'origin-job-missing' });
    expect(select([false], [JsonNumber.int(0)]).ok).toBe(true);
    expect(select([true], [JsonNumber.int(1)]).ok).toBe(true);
    expect(
      select(
        new JsonObject([
          ['b', JsonNumber.int(2)],
          ['a', JsonNumber.int(1)],
        ]),
        new JsonObject([
          ['a', JsonNumber.float(1)],
          ['b', JsonNumber.int(2)],
        ]),
      ).ok,
    ).toBe(true);
    expect(select([false], [JsonNumber.int(1)])).toEqual({
      ok: false,
      refusal: 'revalidation-lineage-mismatch',
    });
    expect(select(JsonNumber.int(1), '1')).toEqual({
      ok: false,
      refusal: 'revalidation-lineage-mismatch',
    });
  });

  test('selection failures are typed and never carry a selected job id', () => {
    const prepared = caseByName('select-prepared');
    const invalidSha = selectJob({ ...selectInputOf(prepared).input, sourceSha: 'not-a-sha' });
    expect(invalidSha).toEqual({ ok: false, refusal: 'source-sha-invalid' });
    const invalidId = selectJob({ ...selectInputOf(prepared).input, jobId: 'bad id' });
    expect(invalidId).toEqual({ ok: false, refusal: 'job-id-invalid' });
    const digest = selectJob({
      ...selectInputOf(prepared).input,
      findingSha256: '0'.repeat(64),
    });
    expect(digest).toEqual({ ok: false, refusal: 'finding-digest-mismatch' });
  });

  test('selection never accepts a queue record that is not queued', () => {
    const entry = caseByName('select-record-state-not-queued');
    expect(selectJob(selectInputOf(entry).input)).toEqual({
      ok: false,
      refusal: 'no-queued-run',
    });
    const extra = caseByName('select-record-jobs-extra');
    expect(selectJob(selectInputOf(extra).input)).toEqual({
      ok: false,
      refusal: 'no-queued-run',
    });
  });

  test('malformed selection inputs are typed refusals, not exceptions', () => {
    const entry = caseByName('select-prepared');
    expect(
      selectJob({
        ...selectInputOf(entry).input,
        queue: new JsonObject([['items', JsonNumber.int(7)]]),
      }),
    ).toEqual({ ok: false, refusal: 'selection-malformed' });
  });
});
